// Classic only, CO-7: the Classic half of hr-v2-payrollrun.test.mjs, kept when its V2 page was removed. Generated by stripping
// every statement that read a deleted V2 file, then retitled for Classic; no assertion was added or changed.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';
const read = (path) =>
    readFileSync(new URL(`../../${path}`, import.meta.url), 'utf8');
const classic = read('resources/js/pages/HR/PayrollRun.vue');
const composable = read('resources/js/composables/hr/usePayrollRunPage.ts');

test('Classic Payroll run takes its requests from usePayrollRunPage', () => {
    assert.match(classic, /usePayrollRunPage\(props\)/);
    assert.match(
        composable,
        /`\/hr\/payroll\/runs\/\$\{props\.run\.id\}\/\$\{step\}`/,
    );
    assert.match(composable, /expected_lock_version: props\.run\.lockVersion/);
});

test('Classic Payroll run confirms with the Classic dialog and uses no V2 part', () => {
    assert.doesNotMatch(classic, /V2WorkLayout|V2Dialog/);
    assert.match(classic, /<OperationalConfirmDialog/);
});
